def solution(nums):
    last = len(nums) - 1
    far = 0                        # farthest pad reachable so far
    for i, jump in enumerate(nums):
        if i > far:
            return False           # pad i is past every reachable pad: stuck
        far = max(far, i + jump)   # every pad up to i + jump is reachable too
        if far >= last:
            return True
    return True

